{v:'VER',what:'the motion layer has an ease-out-back curve that peaks 8 percent past its target and ends on it',
 run:function(){
   if(typeof UIM!=='object'||!UIM||!UIM.E) return 'no motion layer (no UIM)';
   if(typeof UIM.E.back!=='function') return 'no back ease in UIM.E';
   var mx=0, i, v;
   for(i=0;i<=200;i++){ v=UIM.E.back(i/200); if(v>mx) mx=v; }
   if(!(mx>1.06&&mx<1.10)) return 'the back ease peaks at '+mx.toFixed(3)+', want 1.06 to 1.10';
   if(UIM.E.back(0)!==0||UIM.E.back(1)!==1) return 'the back ease does not run 0 to 1';
   return null; }},
